#!/usr/bin/env python3
"""Disassemble arbitrary vaddr ranges from the Go binary using capstone."""
import sys, re, struct
from capstone import *

BIN = '/home/ctfplayer/ctf_files/dist/whitespace_compiler'

def load_sections():
    out = subprocess_run(['readelf', '-SW', BIN])
    secs = []
    for line in out.splitlines():
        m = re.search(r'\[\s*\d+\]\s+(\S+)\s+(\S+)\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([0-9a-f]+)\s', line)
        if m:
            secs.append((m.group(1), int(m.group(3), 16), int(m.group(4), 16), int(m.group(5), 16)))
    return secs

def subprocess_run(cmd):
    import subprocess
    return subprocess.run(cmd, capture_output=True, text=True).stdout

SECS = load_sections()
DATA = open(BIN, 'rb').read()

def v2o(va):
    for name, addr, off, size in SECS:
        if size and addr <= va < addr + size:
            return off + (va - addr), name
    return None, None

def disasm(start, end):
    off, sec = v2o(start)
    if off is None:
        print('unmapped %x' % start); return
    code = DATA[off:off + (end - start)]
    md = Cs(CS_ARCH_X86, CS_MODE_64)
    md.detail = False
    for ins in md.disasm(code, start):
        print('  %x: %-24s %s %s' % (ins.address, ins.bytes.hex(), ins.mnemonic, ins.op_str))

if __name__ == '__main__':
    a, b = int(sys.argv[1], 16), int(sys.argv[2], 16)
    disasm(a, b)

